// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X
plate_wid   = 80;    // plate width along Y
plate_thk   = 3;     // plate thickness (z = 0 to 3)

rib_thk     = 2;     // rib thickness along X
rib_h       = 6;     // rib height above plate (z = 3 to 9)
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs along X
rib_offset  = 20;    // distance from plate end to outer rib centre

eps         = 0.5;   // cutter overshoot past cut faces

$fn = 64;

// ---------------- Derived ----------------
plate_z0 = 0;
plate_z1 = plate_thk;
rib_z0   = plate_z1;
rib_z1   = rib_z0 + rib_h;
x0       = -plate_len/2;   // plate left end
x1       = plate_len/2;    // plate right end

// Check: 3 ribs at pitch 20 span 40 mm; with 20 mm end clearances that fills the 80 mm plate.
assert(abs(2*rib_offset + (rib_count - 1)*rib_pitch - plate_len) < 0.001, "rib layout does not match plate length");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([x0, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on the plate (Y = 0)
    for (i = [0 : rib_count - 1]) {
        x_c = -rib_offset + i * rib_pitch;
        translate([x_c - rib_thk/2, -rib_thk/2, rib_z0])
            cube([rib_thk, rib_thk, rib_h]);
    }
}
```

