```openscad
// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 60;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness (mm), z = 0 to 3

rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 3 to 7
rib_count   = 4;     // number of ribs

rib_pitch   = 16;    // centre-to-centre spacing of ribs (mm)
rib_end_off = 16;    // distance from outer rib centre to plate end (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 64;    // curve resolution

// ---------- Derived ----------
rib_x0 = -rib_end_off;                    // first rib centre X
// check: last rib centre = rib_x0 + (rib_count - 1) * rib_pitch
//                        = -16 + 3*16 = 32 ; plate end = 40 ; offset = 8 mm (OK)

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -rib_thk/2,
                   plate_thk])
            cube([rib_thk, rib_thk, rib_h + eps]);   // extends past top face
    }
}
